const ids=new Set(D.places.map(p=>p.id)),names=new Set(D.places.map(p=>(p.name+"|"+p.country).toLowerCase()));
const validCountry=new Set(D.countries.map(c=>c.code));
for(const r of D.resortReviews){
  if(!validCountry.has(r.country))continue;
  const id=["euronat","valalta","koversada","ulika"].includes(r.id)?r.id:"resort-"+r.id;
  if(ids.has(id)||names.has((r.name+"|"+r.country).toLowerCase()))continue;
  D.places.push({id,country:r.country,name:r.name,area:r.area,coords:r.coords,type:"resort",status:"managed",source:"Operator website / naturist directory — see editorial resort profile",url:r.url,
    summary:r.policy+". "+r.positive,planning:"The pin marks an approximate locality, not a resort entrance. Check the operator's latest rules, fees, availability and dress policy.",editorialLevel:"review",checked:r.editorialDate,reviewRef:r.id});
  ids.add(id);
}
